class ListeViewModel(private val depot: ListeDepot) : ViewModel() {
    private val _elements = MutableStateFlow<List<String>>(emptyList())
    val elements: StateFlow<List<String>> = _elements.asStateFlow()

    fun charger() {
        viewModelScope.launch {
            _elements.value = withContext(Dispatchers.Default) {
                depot.lire().filter { it.isNotBlank() }.sorted()
            }
        }
    }
}

interface ListeDepot {
    suspend fun lire(): List<String>
}

