fun planifierEnvoi(context: Context, fichier: String) {
    val requete = OneTimeWorkRequestBuilder<EnvoiWorker>()
        .setInputData(workDataOf("fichier" to fichier))
        .setConstraints(
            Constraints.Builder()
                .setRequiredNetworkType(NetworkType.UNMETERED)
                .setRequiresBatteryNotLow(true)
                .build()
        )
        .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
        .build()

    WorkManager.getInstance(context).enqueue(requete)
}

fun planifierNettoyage(context: Context) {
    val requete = PeriodicWorkRequestBuilder<NettoyageWorker>(6, TimeUnit.HOURS).build()

    WorkManager.getInstance(context).enqueueUniquePeriodicWork(
        "nettoyage",
        ExistingPeriodicWorkPolicy.KEEP,
        requete,
    )
}

class NettoyageWorker(
