) : CoroutineWorker(context, parametres) {
    override suspend fun doWork(): Result = Result.success()
}

fun travailBref(context: Context, travail: () -> Unit) {
    val alimentation = context.getSystemService(PowerManager::class.java)
    val verrou = alimentation.newWakeLock(
        PowerManager.PARTIAL_WAKE_LOCK,
        "notes:travail",
    )
    verrou.acquire(10_000L)
    try {
        travail()
    } finally {
        if (verrou.isHeld) verrou.release()
    }
}

