#include <jni.h>
#include <string>

extern "C" JNIEXPORT jstring JNICALL
Java_com_exemple_notes_Calcul_saluer(JNIEnv* env, jobject self, jstring nom) {
    const char* brut = env->GetStringUTFChars(nom, nullptr);
    if (brut == nullptr) {
        return nullptr;
    }

    std::string message = std::string("Bonjour, ") + brut;
    env->ReleaseStringUTFChars(nom, brut);

    return env->NewStringUTF(message.c_str());
}

